function diffLines(aLines, b) {
  const added = []
  const removed = []
  const aSet = new Set(aLines)
  const bSet = new Set(b)

  for (const line of aLines) {
    if (!bSet.has(line)) removed.push(line)
  }
  for (const line of b) {
    if (!aSet.has(line)) added.push(line)
  }

  return { added, removed }
}
